# Étienne Brûlé : Donald H. Kent, « The Myth of Etienne Brulé », Pennsylvania History, vol. 43, n° 4, 1976, p. 291-306 ;
# Jules Tremblay, « La sépulture d'Étienne Brûlé », Mémoires de la Société royale du Canada, 3e série, t. IX, 1915, sect. I, p. 145-170
# (PDF du Drive de l'auteur, dossier ETIENNE_BRULE). Préfixes KE76 et TB15.
from commun import Corpus
KE = "Kent, Donald H. (1976), « The Myth of Etienne Brulé », Pennsylvania History, vol. 43, n° 4, p. 291-306"
TB = "Tremblay, Jules (1915), « La sépulture d'Étienne Brûlé », Mémoires de la Société royale du Canada, 3e série, t. IX, section I, p. 145-170"
C1 = Corpus('Recherches', 'KE76', KE, page_fmt='p. {}')
C1.F('01', "Carantouan et la Susquehanna : le voyage d'Étienne Brûlé (1615-1616), un mythe ?", 'exploration', '1615-09~/1616-04~', -76.52, 42.00, 'h', ['Étienne Brûlé', 'Samuel de Champlain'],
  "Selon son propre récit, rapporté par Champlain dans ses Voyages de 1619, Étienne Brûlé aurait visité en 1615 le village allié de Carantouan, puis descendu une rivière jusqu'à la mer pendant l'hiver 1615-1616 : les historiens américains en ont fait le premier Blanc à explorer la Susquehanna et la Pennsylvanie, plaçant Carantouan sur la Chemung, au nord d'Athens. Donald Kent montre que tout repose sur cette seule source, supprimée de l'édition de 1632 des Voyages, racontée par un homme mal famé dans une situation délicate : rien ne permet de situer Carantouan ni d'identifier la rivière. Restent à Brûlé d'autres « premières » : le lac Supérieur, le saut Sainte-Marie, le cuivre du lac Supérieur et sans doute le dictionnaire huron de Sagard.",
  '291-306', "Point hypothétique sur la Chemung, au nord d'Athens (Pennsylvanie), emplacement que Kent récuse.")
C2 = Corpus('Recherches', 'TB15', TB, page_fmt='p. {}')
C2.F('01', "Toanché (pointe de Penetanguishene) : la mort et la sépulture d'Étienne Brûlé (juin 1633)", 'evenement', '1633-06', -79.95, 44.82, 'a', ['Étienne Brûlé', 'Aénons', 'Jean de Brébeuf'],
  "Arrivé en Huronie en 1610 dans le canot d'Aénons, chef du village de Toanché (tribu de l'Ours), Brûlé y vécut avec sa famille. En juin 1633, il y est mis à mort et mangé ; ses restes ne furent jamais portés à l'ossuaire de la fête des Morts. Le village est abandonné et remplacé par Oenrio et Toanché II ; en 1634, Brébeuf, débarqué au port de Toanché, passe devant « l'endroit où le pauvre Estienne Bruslé avait été barbarement et traîtreusement assommé ». Jules Tremblay situe la fosse sur la moitié est du lot 1 de la 17e concession du canton de Tiny (comté de Simcoe), sur la ferme des Grozelle, où les labours ont révélé un site de village huron.",
  '145-152', "Localisation proposée par Tremblay (1915) ; point approximatif sur la pointe de Penetanguishene (Ontario).")
C2.F('02', "Otouacha, port de Toanché : Champlain touche terre en Huronie, guidé par Brûlé (1er août 1615)", 'exploration', '1615-08-01', -79.965, 44.815, 'a', ['Samuel de Champlain', 'Étienne Brûlé'],
  "Champlain écrit qu'il arriva le premier jour d'août 1615 au pays des Attignaouantans (tribu de l'Ours), à un village nommé Otouacha, dans un pays de collines et de ruisseaux, à une lieue de Carmaron (Karenhassa). Suivant les triangulations du père Jones (Old Huronia, 1908), Tremblay place Otouacha, « le double atterrissage », au bord de l'eau, sur la falaise et la grève du lot A de la XVIe concession de Tiny : c'est le port du premier Toanché, où Brûlé conduisait Champlain.", '146-147, 152', "Localisation proposée par Jones et Tremblay.")
C2.F('03', "Carhagouha : le récollet Le Caron dit la première messe de l'Ontario (12 août 1615)", 'religion', '1615-08-12', -80.030, 44.740, 'a', ['Joseph Le Caron', 'Samuel de Champlain'],
  "Carhagouha, le fort à triple palissade décrit par Champlain, est le lieu où le père Joseph Le Caron célèbre le 12 août 1615 la première messe dite en Ontario ; dès 1626, le fort est réduit à peu de chose et absorbé par le triple bourg de Khinonascarant, où réside Le Caron au temps de Sagard. Les fouilles en situent l'emplacement sur le lot 20 de la XVIIe concession de Tiny, ferme de Philias Beaupré, dans la paroisse de Lafontaine.", '148-149, 152')
C2.F('04', "Québec : la flottille huronne craint des représailles pour la mort de Brûlé ; Amantacha la rassure (juillet 1633)", 'evenement', '1633-07-28', -71.208, 46.813, 'c', ['Louis Amantacha', 'Samuel de Champlain', 'Paul Le Jeune', 'Aénons'],
  "Selon le père Le Jeune, les Algonquins de l'Île et de la Petite Nation cherchent à dissuader les Hurons de descendre à Québec en prétendant qu'on leur ferait payer le meurtre d'Étienne Brûlé. Envoyé au-devant d'eux par Champlain, Louis Amantacha (de la tribu de la Corde) leur assure la bienveillance des Français : Brûlé, passé au service des Anglais, n'était plus tenu pour Français. Le 28 juillet 1633, quelque cent quarante canots portant cinq cents à sept cents Hurons arrivent à Québec. Par recoupement des dates, Tremblay conclut que Brûlé fut assommé à Toanché dans la première semaine de juin 1633.", '153-155')
C2.F('05', "Ihonatiria : Brébeuf revoit le lieu du meurtre de Brûlé et fonde la première mission fixe (1634-1638)", 'religion', '1634-08-05/1638', -79.990, 44.845, 'a', ['Jean de Brébeuf', 'Aénons', 'Étienne Brûlé', 'Guillaume Chaudron'],
  "Revenu en Huronie le 5 août 1634, Brébeuf débarque au port déserté de Toanché, cherche le nouveau village (Teandeouiata, à trois quarts de lieue) et voit en passant l'emplacement de l'ancienne résidence changé en champ et « l'endroit où le pauvre Estienne Bruslé avait été barbarement et traîtreusement assommé ». Le village s'était dispersé après ce meurtre ; ses habitants viennent se cabaner autour du missionnaire à Ihonatiria, fondée en octobre 1634 au bord du lac Huron, en face de l'île Giant's Tomb, et abandonnée en 1638. En 1636, les Hurons de l'Ours proposent de relever les corps de Guillaume Chaudron et de Brûlé.", '145-146, 149-153', "Lot 6, concessions XX et XXI de Tiny, selon Jones et Tremblay.")
fiches = C1.fiches + C2.fiches
